#!/usr/bin/env python3
"""Generate lib/core/navigation/routes.g.dart from tools/routes.json."""
import json
from pathlib import Path

here = Path(__file__).parent
data = json.loads((here / "routes.json").read_text())

lines = [
    "// GENERATED by tools/generate_routes.py - do not edit by hand.",
    "abstract final class GeneratedRoutes {",
]
for r in data["routes"]:
    const = "_".join(part.upper() for part in r.replace("-", "_").split("_"))
    lines.append(f"  static const {const} = '{r}';")
lines.append("}")
lines.append("")
lines.append("const generatedPhrases = <String, List<String>>{")
for route, phrases in data["phrases"].items():
    joined = ", ".join(f"'{p}'" for p in phrases)
    lines.append(f"  '{route}': [{joined}],")
lines.append("};")

out = here.parent / "lib" / "core" / "navigation" / "routes.g.dart"
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text("\n".join(lines) + "\n")
print(f"wrote {out}")
